"use client";

import { useSession } from "next-auth/react";
import { useState } from "react";
import Layout from "@/components/layout";

export default function ProfilePage() {
  const { data: session } = useSession();
  const [selectedIcon, setSelectedIcon] = useState(session?.user?.avatar || null);

  if (!session) {
    return (
      <Layout>
        <p className="text-center p-10">Gelieve in te loggen om je profiel te bekijken.</p>
      </Layout>
    );
  }

  const icons = [
    { id: "icon1", label: "🧑‍💻" },
    { id: "icon2", label: "👩‍🎨" },
  ];

  return (
    <Layout>
      <div className="max-w-xl mx-auto space-y-6">
        <h1 className="text-3xl font-bold">Welkom, {session.user?.email}</h1>

        <h2 className="text-xl font-semibold">Je avatar</h2>
        <div className="flex gap-6">
          {icons.map((icon) => (
            <button
              key={icon.id}
              onClick={() => setSelectedIcon(icon.id)}
              className={`text-4xl p-4 rounded-xl border-2 transition ${
                selectedIcon === icon.id ? "border-blue-500 bg-blue-100" : "border-gray-300"
              }`}
            >
              {icon.label}
            </button>
          ))}
        </div>

        {session.user?.role === "ADMIN" && (
          <div className="mt-6 p-4 bg-yellow-100 rounded-xl border-l-4 border-yellow-500">
            <h3 className="font-semibold">Admin Panel</h3>
            <p>Hier kan je admin-only acties uitvoeren.</p>
          </div>
        )}
      </div>
    </Layout>
  );
}